package eventbus_test

import (
	"testing"

	"github.com/ai-verification/go-eventbus/internal/eventbus"
)

func TestPublishToSubscriber(t *testing.T) {
	bus := eventbus.New()
	received := []string{}
	bus.Subscribe("news", func(msg string) { received = append(received, msg) })
	bus.Publish("news", "hello")
	if len(received) != 1 || received[0] != "hello" {
		t.Fatalf("expected [hello], got %v", received)
	}
}

func TestMultipleSubscribers(t *testing.T) {
	bus := eventbus.New()
	var a, b []string
	bus.Subscribe("topic", func(msg string) { a = append(a, msg) })
	bus.Subscribe("topic", func(msg string) { b = append(b, msg) })
	bus.Publish("topic", "event")
	if len(a) != 1 || len(b) != 1 {
		t.Fatalf("expected both subscribers to receive: a=%v b=%v", a, b)
	}
}

func TestUnsubscribe(t *testing.T) {
	bus := eventbus.New()
	received := []string{}
	id := bus.Subscribe("alerts", func(msg string) { received = append(received, msg) })
	bus.Publish("alerts", "first")
	bus.Unsubscribe(id)
	bus.Publish("alerts", "second")
	if len(received) != 1 || received[0] != "first" {
		t.Fatalf("expected only [first] after unsubscribe, got %v", received)
	}
}

func TestDifferentTopicsIsolated(t *testing.T) {
	bus := eventbus.New()
	var newsItems, weatherItems []string
	bus.Subscribe("news", func(msg string) { newsItems = append(newsItems, msg) })
	bus.Subscribe("weather", func(msg string) { weatherItems = append(weatherItems, msg) })
	bus.Publish("news", "breaking")
	if len(newsItems) != 1 || len(weatherItems) != 0 {
		t.Fatalf("news=%v weather=%v", newsItems, weatherItems)
	}
}

func TestPublishNoSubscribersDoesNotPanic(t *testing.T) {
	bus := eventbus.New()
	bus.Publish("empty", "nobody listening")
}

